-- Required missing actors and researched Lelluran nightmare placeholders.
-- Whole-package transaction required; original spawn2 geometry is never updated.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_npcs`;
CREATE TEMPORARY TABLE `_dragonscale_world_npcs` LIKE `npc_types`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_old`;
CREATE TEMPORARY TABLE `_dragonscale_world_old` LIKE `spawnentry`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_new`;
CREATE TEMPORARY TABLE `_dragonscale_world_new` LIKE `spawnentry`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_spell_list`;
CREATE TEMPORARY TABLE `_dragonscale_world_spell_list` LIKE `npc_spells`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_spells`;
CREATE TEMPORARY TABLE `_dragonscale_world_spells` LIKE `npc_spells_entries`;
DROP TEMPORARY TABLE IF EXISTS `_dragonscale_world_guard`;
CREATE TEMPORARY TABLE `_dragonscale_world_guard`(ok INT NOT NULL CHECK(ok=1));
DELETE a FROM spawnentry a JOIN `_dragonscale_world_old` o ON a.spawngroupID=o.spawngroupID;
SET @dragonscale_world_ok=1;
